<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>习题 11.1</title>
<script type="text/javascript" id="MathJax-script" async
  src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js">
</script>
<style>
  body {
    font-family: "SimSun", "STSong", serif;
    max-width: 700px;
    margin: 0 auto;
    padding: 20px 30px;
    color: #222;
    font-size: 15px;
    line-height: 1.8;
  }
  .header-bar {
    background: linear-gradient(to right, #c9a86a, #e8d9b5);
    color: #fff;
    padding: 6px 15px;
    font-size: 20px;
    font-weight: bold;
    margin-bottom: 20px;
  }
  h2.section-title {
    font-size: 17px;
    font-weight: bold;
    border-bottom: 2px solid #333;
    display: inline-block;
    margin-top: 25px;
    margin-bottom: 12px;
  }
  .problem {
    margin-bottom: 14px;
  }
  .problem-num {
    font-weight: bold;
  }
  .figure-block {
    text-align: center;
    margin: 10px 0;
  }
  .fig-caption {
    font-size: 13px;
    margin-top: 4px;
  }
  .placeholder {
    border: 1px dashed #999;
    background: #fafafa;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #777;
    font-size: 13px;
    margin: 0 auto;
  }
  .triple-figs {
    display: flex;
    justify-content: space-around;
    gap: 10px;
    margin: 10px 0;
  }
  .triple-figs .placeholder {
    flex: 1;
  }
  .fillblank {
    margin: 6px 0 6px 25px;
  }
